            pattern: '^[0-9a-f]{128}$|^[0-9a-f]{130}$',
            example: '461a4ccffafea42dd965e80752e2703e53b74ca36813db2529ff32794063d98f46b7655fbb62c08ae4bd8e6234ccb9115b93bf5d1d6d8254afd89c4767d00e891b'
