export const $ErrorResponse = {
    type: 'object',
    description: `Safe, outward-facing error derived from an internal error through the shared error catalog (schemas/apis/error/v1). The error shape these endpoints return for a handled failure.

A panic is caught by gin's Recovery, which sends 500 with an empty body, so a 500 is not guaranteed to carry this shape.`,
    required: ['code', 'message'],
    properties: {
        code: {
            type: 'string',
            description: 'Public, machine-readable error code in SCREAMING_SNAKE_CASE.',
            pattern: '^[A-Z][A-Z0-9_]*$',
            example: 'CHAIN_NOT_SUPPORTED'
        },
        message: {
            type: 'string',
            description: 'Curated, safe, human-readable message.',
            example: 'The requested chain is not supported.'
        },
        request_id: {
            type: 'string',
            description: 'Correlation id for locating the internal error record.',
            example: 'req_123456789'
        },
        payment_id: {
            type: 'string',
            description: 'The payment this error was raised against. Absent when the error is not about a specific payment.',
            example: '0xc7108e200d11580e7e75185991084b42a535af588ba8267cd0d1e7df089e5c9c'
        },
        docs_url: {
            type: 'string',
            format: 'uri',
            description: 'Link to the documentation page for this public code.'
        },
        domain: {
            type: 'string',
            description: 'Originating service domain.',
            example: 'VERIFICATION_SERVICE'
        },
        retry_classification: {
            type: 'string',
            description: `What the caller should do next. Absent means the condition has not been classified, which is not the same as safe to retry.
Re-sending the same \`request_id\` is an idempotent replay and always safe. This value is about submitting a new one, which starts a new operation. See https://docs.atum.xyz/errors for the value set.`,
            example: 'RECONCILE_THEN_DECIDE'
        },
        request_id_reusable: {
            type: 'boolean',
            description: 'Whether the caller may re-send this same request_id. True means no payment was created for it, so the id is still free. False means a payment exists for it, so the id is spent and re-sending only replays this outcome. Absent means undetermined, which a caller should read as false. Separate from retry_classification, which answers what the caller must change rather than whether the id survived.',
            example: false
        }
    }
} as const;

